#!/usr/bin/env python3

# Copyright (c) 2026 Föreningen Sambruk
#
# Prepares the SPDX documents generated by vcpkg so they can be merged
# with vcpkg-sbom.
#
# vcpkg only lists SHA256 checksums for files, but SPDX 2.3 requires a
# SHA1 checksum for each file. vcpkg-sbom tries to add it by reading the
# files relative to the current directory, which fails since vcpkg uses
# paths relative to each port/package directory
# (see https://github.com/moverseai/vcpkg-sbom/issues/1).
#
# This script copies the SPDX documents for a triplet, removing the
# file entries (and relationships referring to them). Package level
# information is kept as is.

import argparse
import json
import pathlib
import sys

def strip_files(doc):
    file_ids = {f['SPDXID'] for f in doc.get('files', [])}
    doc.pop('files', None)
    doc['relationships'] = [r for r in doc.get('relationships', [])
                            if r['spdxElementId'] not in file_ids
                            and r['relatedSpdxElement'] not in file_ids]

if __name__ == '__main__':

    parser = argparse.ArgumentParser(description='Copy vcpkg SPDX documents without file entries')

    parser.add_argument('source',
                        help='vcpkg installed directory for a triplet, e.g. build/vcpkg_installed/x64-windows')
    parser.add_argument('destination',
                        help='directory to write the stripped SPDX documents to')

    args = parser.parse_args()

    source = pathlib.Path(args.source)
    destination = pathlib.Path(args.destination)

    # Same pattern as vcpkg-sbom uses to find the documents
    paths = sorted(source.glob('**/share/**/*.spdx.json'))
    if not paths:
        print('No SPDX documents found in', source)
        sys.exit(1)

    for path in paths:
        with open(path, 'r', encoding='utf-8') as f:
            doc = json.load(f)

        strip_files(doc)

        out_path = destination / path.relative_to(source)
        out_path.parent.mkdir(parents=True, exist_ok=True)
        with open(out_path, 'w', encoding='utf-8') as f:
            json.dump(doc, f, indent=2)

    print('Stripped file entries from', len(paths), 'SPDX documents')
